/* ============================================================================
   sounds.js: what a window says by ear, and the switch that keeps it quiet.

   Some of a window's work is done by somebody who is looking elsewhere: at a
   bench, at a device in the hand, at the thing being measured. The few things
   worth knowing at once are said by ear as well as on screen. Seven voices,
   named for what they say and not for how they sound:

     forward    back        a step on, or into a part of the window; a step
                            back, or back to the start
     confirm                done as asked: saved, worked out
     shutter                a picture taken
     error                  it did not work
     on         off         something switched on, or off: a view, a device,
                            the sounds themselves

     initSounds({ hints: { on: 'Sounds on', off: 'Sounds off' } });
     <button data-sound="forward">Next</button>
     playSound('confirm');

   WHERE THEY COME FROM. Every voice is cut from Kenney's "Interface Sounds"
   and "UI Audio" (kenney.nl), which are in the public domain under CC0 1.0:
   two small glass bells, struck and left to ring or damped at once, and two
   clicks. Cut to their sound, the lower ones pitched down a fourth by
   resampling, faded in over half a millisecond and out over the last part of
   their tail, so the first and the last sample of each are zero, and all
   brought to one loudness, SOUND_LOUDNESS (LUFS, weighted as ITU-R BS.1770
   weights it, half on a 400 ms window and half on a 125 ms one). The
   samples are in SOUND_DATA below, 16 bit at 48 kHz, one channel: nothing is
   loaded from anywhere and nothing is made on the spot. No glide, no low
   note: the lowest fundamental is the error's, at a little over 1 kHz.

   AT ONCE. A sound that comes late is worse than none, because the ear puts
   it with whatever happened last. So every voice is turned into an audio
   buffer when the page says it has sounds, the audio context (latency hint
   "interactive") is opened then and kept running, and a voice is started
   the moment it is asked for, with nothing to build: one buffer source and
   one gain. A control says which voice it makes with `data-sound`, and the
   voice is played on the press itself (pointerdown, or Enter and Space on
   the focused control), never on the release and never after an answer
   from the application. soundLatency() says what the engine adds on top:
   the context's own buffer and the device's. A context that has played
   only silence for a while may have its device closed by the engine
   (Chromium moves it to a silent stand-in after some seconds), and the next
   voice then waits for the device to open again, a tenth of a second or
   more. So while sounds are on a level far under hearing (SOUND_AWAKE,
   about -130 dB, constant: no tone) keeps the device open, and every voice
   starts at once.

   NO BURSTS. A voice asked for again inside its own gap is dropped, and so
   is one asked for within SOUND_NEAR_MS of another that says as much or
   more; one that says more plays, and the other gives way to it over a few
   milliseconds. Over any second at most SOUND_BURST play.

   THE SWITCH. initSounds() puts a speaker among the window buttons, and
   Ctrl+M flips it from anywhere in the window. Sounds are on until somebody
   turns them off, and what they chose is kept: in the page's local storage,
   or by the application through `keep`, since a window whose engine forgets
   its storage on closing (as an embedded browser's default one does) only
   remembers through the application. Until initSounds() is called nothing
   plays at all, because until then the page has not said whether the person
   using it wants to hear anything. The words on the switch are the
   application's, like every word on the band.

   Leaves on the window: SOUND_VOICES, SOUND_DATA, SOUND_RATE,
   SOUND_LOUDNESS, SOUND_KEY, SOUND_NEAR_MS, SOUND_BURST, initSounds,
   playSound, soundsOn, setSoundsOn, setSoundHints, soundLength,
   soundLatency, renderSound.
   ========================================================================== */

const SOUND_RATE = 48000;
const SOUND_LOUDNESS = -32;
const SOUND_KEY = 'm';            // with Ctrl
const SOUND_NEAR_MS = 60;
const SOUND_BURST = 5;

/* What each voice says, by how much (a step least, a failure most), and how
   soon it may come again, in ms. */
const SOUND_VOICES = {
  forward: { prio: 0, gap: 50 },
  back: { prio: 0, gap: 50 },
  shutter: { prio: 1, gap: 100 },
  on: { prio: 1, gap: 100 },
  off: { prio: 1, gap: 100 },
  confirm: { prio: 2, gap: 300 },
  error: { prio: 3, gap: 500 },
};

const _GIVE_WAY_S = 0.004;        // how fast a voice that says less fades for one that says more
const _RESUME_LATE_MS = 150;
const SOUND_AWAKE = 3e-7;          // the level that keeps the device open while sounds are on (far under hearing)      // a sound still waiting for the device after this long is not played

const _snd = {
  ready: false, on: true, volume: 1, hints: null, keep: null, wired: false,
  ctx: null, buffers: null, cur: null, last: {}, recent: [], flash: null, samples: {}, awake: null,
};
const _SND_STORE = 'slantui.sounds';

function _sndClock() {
  return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
}

/* Base64 by hand: the engine has atob, a test harness may not. */
const _B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function _sndBytes(s) {
  const map = {};
  for (let i = 0; i < 64; i++) map[_B64.charAt(i)] = i;
  const clean = s.replace(/=+$/, '');
  const out = new Uint8Array(Math.floor(clean.length * 3 / 4));
  let o = 0;
  for (let i = 0; i < clean.length; i += 4) {
    const a = map[clean.charAt(i)], b = map[clean.charAt(i + 1)];
    const c = map[clean.charAt(i + 2)], d = map[clean.charAt(i + 3)];
    const n = (a << 18) | (b << 12) | ((c || 0) << 6) | (d || 0);
    if (o < out.length) out[o++] = (n >> 16) & 255;
    if (o < out.length) out[o++] = (n >> 8) & 255;
    if (o < out.length) out[o++] = n & 255;
  }
  return out;
}

/* A voice's samples, -1 to 1, worked out once. */
function _sndSamples(name) {
  if (_snd.samples[name]) return _snd.samples[name];
  const b = _sndBytes(SOUND_DATA[name] || '');
  const x = new Float32Array(b.length >> 1);
  for (let i = 0; i < x.length; i++) {
    let v = b[2 * i] | (b[2 * i + 1] << 8);
    if (v >= 32768) v -= 65536;
    x[i] = v / 32768;
  }
  _snd.samples[name] = x;
  return x;
}

/* How long a voice sounds, in ms. */
function soundLength(name) {
  return SOUND_DATA[name] ? _sndSamples(name).length / SOUND_RATE * 1000 : 0;
}

/* Every voice as a buffer of this context, made once. */
function _sndPrepare(ctx) {
  const out = {};
  for (const name in SOUND_VOICES) {
    const x = _sndSamples(name);
    if (!x.length) continue;
    const buf = ctx.createBuffer(1, x.length, SOUND_RATE);
    buf.getChannelData(0).set(x);
    out[name] = buf;
  }
  return out;
}

/* One voice into `dest`, now. Returns what plays it. */
function _sndStart(ctx, dest, name, level) {
  const src = ctx.createBufferSource(), g = ctx.createGain();
  src.buffer = (_snd.buffers && _snd.ctx === ctx ? _snd.buffers : _sndPrepare(ctx))[name];
  g.gain.value = level;
  src.connect(g);
  g.connect(dest);
  src.onended = function () { try { g.disconnect(); } catch (e) { /* gone already */ } };
  src.start();
  return { src: src, gain: g };
}

/* A voice as samples, one channel at `rate` (SOUND_RATE when not said), at
   volume 1, through the same nodes playSound() uses, by the engine's own
   offline renderer. Resolves to a Float32Array, or null where the engine has
   no offline renderer. */
function renderSound(name, rate) {
  const OAC = typeof window !== 'undefined' && (window.OfflineAudioContext || window.webkitOfflineAudioContext);
  if (!SOUND_VOICES[name] || !OAC) return Promise.resolve(null);
  rate = rate || SOUND_RATE;
  const ctx = new OAC(1, Math.ceil((soundLength(name) / 1000 + 0.02) * rate), rate);
  _sndStart(ctx, ctx.destination, name, 1);
  return ctx.startRendering().then(function (buf) { return buf.getChannelData(0); });
}

/* ── the device ────────────────────────────────────────────────────────── */
function _sndContext() {
  if (_snd.ctx) return _snd.ctx;
  const AC = typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext);
  if (!AC) return null;
  try { _snd.ctx = new AC({ latencyHint: 'interactive' }); } catch (e) { _snd.ctx = null; }
  if (_snd.ctx) _snd.buffers = _sndPrepare(_snd.ctx);
  _sndAwake();
  return _snd.ctx;
}

/* The device kept open while sounds are on (see AT ONCE), closed when off. */
function _sndAwake() {
  const ctx = _snd.ctx, want = !!(ctx && _snd.ready && _snd.on);
  if (want === !!_snd.awake || (want && typeof ctx.createConstantSource !== 'function')) return;
  try {
    if (want) {
      const src = ctx.createConstantSource();
      src.offset.value = SOUND_AWAKE;
      src.connect(ctx.destination);
      src.start();
      _snd.awake = src;
    } else {
      _snd.awake.stop();
      _snd.awake.disconnect();
      _snd.awake = null;
    }
  } catch (e) { _snd.awake = null; }
}

/* What the engine adds between a voice started and the ear, in ms: the
   context's own buffer and the device's, as the engine reports them, or null
   before there is a context. */
function soundLatency() {
  const ctx = _snd.ctx;
  if (!ctx) return null;
  const base = (ctx.baseLatency || 0) * 1000, output = (ctx.outputLatency || 0) * 1000;
  return { base: base, output: output, total: base + output, rate: ctx.sampleRate, state: ctx.state };
}

/* The voice that was playing gives way to one that says more. */
function _sndGiveWay(cur, ctx) {
  try {
    const t = ctx.currentTime;
    cur.out.gain.gain.setTargetAtTime(0, t, _GIVE_WAY_S);
    cur.out.src.stop(t + 8 * _GIVE_WAY_S);
  } catch (e) { /* it ends by itself a moment later */ }
}

/* Play a voice, if sounds are on and it is not one too many. Returns whether
   it was sent to the device. */
function playSound(name) {
  const v = SOUND_VOICES[name];
  if (!v || !_snd.ready || !_snd.on || !(_snd.volume > 0)) return false;
  const now = _sndClock(), prio = v.prio || 0;
  if (_snd.last[name] !== undefined && now - _snd.last[name] < v.gap) return false;
  const near = _snd.cur && now - _snd.cur.at < SOUND_NEAR_MS ? _snd.cur : null;
  if (near && prio <= near.prio) return false;
  _snd.recent = _snd.recent.filter(function (t) { return now - t < 1000; });
  if (_snd.recent.length >= SOUND_BURST) return false;
  const ctx = _sndContext();
  if (!ctx) return false;
  _snd.last[name] = now;
  _snd.recent.push(now);
  const cur = { name: name, prio: prio, at: now, out: null };
  if (near && near.out) _sndGiveWay(near, ctx);
  _snd.cur = cur;
  const start = function () {
    try { cur.out = _sndStart(ctx, ctx.destination, name, _snd.volume); } catch (e) { /* silent, then */ }
  };
  if (ctx.state === 'running') start();
  else {
    // not yet allowed to start: the sound waits for the device, and is dropped if it comes too late
    try {
      ctx.resume().then(function () { if (_sndClock() - now < _RESUME_LATE_MS) start(); }, function () {});
    } catch (e) { return false; }
  }
  return true;
}

/* ── the switch ────────────────────────────────────────────────────────── */
function soundsOn() { return _snd.ready && _snd.on; }

function _sndKept() {
  try {
    const v = window.localStorage.getItem(_SND_STORE);
    return v === null ? null : v === '1';
  } catch (e) { return null; }
}

function _sndKeep(on) {
  if (_snd.keep) {
    try { _snd.keep(on); } catch (e) { /* the application's, and its own business */ }
    return;
  }
  try { window.localStorage.setItem(_SND_STORE, on ? '1' : '0'); } catch (e) { /* not kept, then */ }
}

function _sndButton() {
  const bar = typeof document !== 'undefined' && document.querySelector('.titlebar');
  return bar ? bar.querySelector('.wbtn-sound') : null;
}

function _sndShow() {
  const b = _sndButton();
  if (!b) return;
  setIcon(b, _snd.on ? 'sound-on' : 'sound-off');
  b.setAttribute('aria-pressed', _snd.on ? 'true' : 'false');
  /* The switch is a drawing and no word; under the pointer it says what it
     is in the application's words, and with none given at least the key. */
  const hint = (_snd.hints && _snd.hints[_snd.on ? 'on' : 'off']) || 'Ctrl+M';
  b.title = hint;
  b.setAttribute('aria-label', hint);
}

/* Sounds on or off, as the person using the window chose: said by the
   voice of the switch (the one going off is the last sound before the
   quiet), shown on the switch and kept. Returns the state. */
function setSoundsOn(on) {
  on = !!on;
  if (!_snd.ready || on === _snd.on) return soundsOn();
  if (!on) playSound('off');
  _snd.on = on;
  _sndAwake();
  if (on) playSound('on');
  _sndKeep(on);
  _sndShow();
  return on;
}

/* The words on the switch, in the application's language: { on, off }, the
   one that is true now shown. Called again whenever the language changes. */
function setSoundHints(hints) {
  _snd.hints = hints || null;
  _sndShow();
}

/* The speaker, first among the window buttons, a little apart from them
   (components.css, .wbtn-sound). It flips on the press, like every other
   control that makes a sound. */
function _sndSwitch() {
  const btns = typeof document !== 'undefined' && document.querySelector('.tbar-btns');
  if (!btns) return null;
  let b = btns.querySelector('.wbtn-sound');
  if (!b) {
    b = document.createElement('div');
    b.className = 'wbtn wbtn-sound';
    b.setAttribute('role', 'button');
    btns.insertBefore(b, btns.children[0] || null);
  }
  b.onpointerdown = function (e) { if (!e || e.button === 0 || e.button === undefined) setSoundsOn(!_snd.on); };
  _sndShow();
  return b;
}

/* Ctrl+M, from anywhere: the switch lights for a moment, so the eye finds
   what the key did. */
function _sndKey(e) {
  if (!e.ctrlKey || e.altKey || e.shiftKey || e.metaKey || e.repeat) return;
  const k = String(e.key || '').toLowerCase();
  if (k !== SOUND_KEY && !(e.code === 'KeyM' && !/^[a-z]$/.test(k))) return;
  e.preventDefault();
  setSoundsOn(!_snd.on);
  const b = _sndButton();
  if (!b) return;
  b.classList.add('on');
  clearTimeout(_snd.flash);
  _snd.flash = setTimeout(function () { b.classList.remove('on'); }, 600);
}

/* The control a press landed on that says it makes a sound, or null. Walked
   by hand, with no selector, so the same code runs in any document. */
function _sndControl(el) {
  for (let n = el; n && typeof n.getAttribute === 'function'; n = n.parentNode) {
    if (n.getAttribute('data-sound') !== null) return n;
  }
  return null;
}

/* The press: the voice of the control it landed on, now. A control that is
   off says nothing, and nor does a key somebody else has already used. */
function _sndPress(e) {
  if (e.type === 'pointerdown' && e.button !== 0) return;
  if (e.type === 'keydown' && ((e.key !== 'Enter' && e.key !== ' ') || e.repeat || e.defaultPrevented
                               || e.ctrlKey || e.altKey || e.metaKey)) return;
  const el = _sndControl(e.target);
  if (!el || el.disabled || el.getAttribute('aria-disabled') === 'true'
      || (el.classList && el.classList.contains('off'))) return;
  const name = el.getAttribute('data-sound');
  if (name) playSound(name);
}

/* Where a page has to be pressed before it may make a sound, the first
   press or key lets the device start. */
function _sndWake() {
  const ctx = _snd.ctx;
  if (ctx && ctx.state === 'suspended') {
    try { ctx.resume(); } catch (e) { /* the next sound asks again */ }
  }
}

/* Say that the page has sounds. `opts`, all optional:
     on      whether they are on, as the application kept it; when not
             given, as this page's storage kept it, and on the first time
     keep    function (on): the application keeps the choice itself
     hints   the words on the switch, { on, off }
     volume  0 to 1, on top of SOUND_LOUDNESS
     band    false: no switch on the band (the key still works)
   Returns the switch, or null when there is none. */
function initSounds(opts) {
  opts = opts || {};
  _snd.keep = typeof opts.keep === 'function' ? opts.keep : null;
  const kept = typeof opts.on === 'boolean' ? opts.on : _sndKept();
  _snd.on = kept === null ? true : kept;
  if (typeof opts.volume === 'number') _snd.volume = Math.max(0, Math.min(1, opts.volume));
  if (opts.hints) _snd.hints = opts.hints;
  _snd.ready = true;
  // the device and every voice made ready now, so that a press is heard at once
  const ctx = _sndContext();
  _sndAwake();
  if (ctx && ctx.state === 'suspended') _sndWake();
  if (!_snd.wired && typeof window !== 'undefined' && window.addEventListener) {
    _snd.wired = true;
    window.addEventListener('keydown', _sndKey, true);
    window.addEventListener('pointerdown', _sndWake, true);
    window.addEventListener('keydown', _sndWake, true);
    window.addEventListener('pointerdown', _sndPress, true);
    window.addEventListener('keydown', _sndPress, true);
  }
  return opts.band === false ? null : _sndSwitch();
}

/* ── the voices ────────────────────────────────────────────────────────── */
/* Cut from the CC0 sources named at the top of this file: each one 16 bit
   little endian samples at SOUND_RATE, one channel, in base64. */
const SOUND_DATA = {
  forward: '',
  back: '',
  shutter: '',
  on: '',
  off: '',
  confirm: '',
  error: '',
};
